#!/usr/bin/env bash
set -euo pipefail
# Regenerates rename.h: every name kode54's fork defines at link level (classes, functions,
# globals), mapped to an rsgc_ prefixed one. The fork is compiled with rename.h force-included,
# so its copies of the chip and file classes it shares with upstream libgme get their own names
# and both live in one library. Run it after moving external/gme-kode54 to a new commit.
#
# Usage: deps/rommusic/sgc/make_rename.sh   (needs a C++ compiler and nm)

here="$(cd "$(dirname "$0")" && pwd)"
root="$(cd "$here/../../.." && pwd)"
fork="$root/external/gme-kode54/gme"
upstream="$root/external/game-music-emu/gme"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
src=(Sgc_Core Sgc_Cpu Sgc_Emu Sgc_Impl Sms_Apu Sms_Fm_Apu Z80_Cpu Classic_Emu Music_Emu Gme_File Gme_Loader
  Rom_Data M3u_Playlist Track_Filter Blip_Buffer Multi_Buffer Effects_Buffer blargg_common blargg_errors gme)
for f in "${src[@]}"; do
  ${CXX:-c++} -c -O0 -w -fpermissive -DHAVE_STDINT_H -DBLARGG_LITTLE_ENDIAN=1 "-DGME_TYPE_LIST=gme_sgc_type" \
    -I"$fork" -I"$upstream" "$fork/$f.cpp" -o "$tmp/$f.o"
done
${CXX:-c++} -c -O0 -w -DHAVE_STDINT_H -DBLARGG_LITTLE_ENDIAN=1 -I"$fork" -I"$upstream" "$upstream/Data_Reader.cpp" -o "$tmp/Data_Reader.o"
${CXX:-c++} -c -O0 -w -I"$fork" "$here/ym2413_off.cpp" -o "$tmp/ym2413_off.o"
{
  echo "// Generated by make_rename.sh: the fork's link-level names, prefixed so they do not"
  echo "// collide with upstream libgme's in the same library. Do not edit by hand."
  echo "#pragma once"
  nm -g -C --defined-only "$tmp"/*.o | awk '{ $1 = ""; $2 = ""; print }' | sed 's/^ *//' \
    | sed -E 's/^(vtable for |typeinfo for |typeinfo name for |guard variable for |VTT for |non-virtual thunk to |virtual thunk to )+//' \
    | grep -Ev '^(std::|__|_GLOBAL|\.|DW\.)' | sed -E 's/^([A-Za-z_][A-Za-z0-9_]*).*/\1/' | grep -E '^[A-Za-z_]' | grep -Evx 'long|int|short|char|unsigned|signed|void|bool|float|double|operator|const' \
    | sort -u | awk '{ printf "#define %s rsgc_%s\n", $1, $1 }'
} > "$here/rename.h"
echo "wrote $here/rename.h ($(grep -c '^#define' "$here/rename.h") names)"
